// Validate the incoming lead payload.
// Required fields: id, name, phone, message.
// Throws a clear error naming the first missing field.
// Logic kept identical to src/validate.js.
const payload = $input.first().json.body || $input.first().json;
const required = ['id', 'name', 'phone', 'message'];

if (payload === null || typeof payload !== 'object') {
  throw new Error('Invalid payload: expected an object');
}

for (const field of required) {
  const value = payload[field];
  if (value === undefined || value === null || value === '') {
    throw new Error('Missing required field: ' + field);
  }
}

return [{ json: payload }];

// Skip a lead id that was already processed.
// Uses workflow static data as the persistent store.
// Logic kept identical to src/dedupe.js.
const store = $getWorkflowStaticData('global');
const payload = $input.first().json;
const id = payload.id;

if (id === undefined || id === null || id === '') {
  throw new Error('Missing lead id for dedupe');
}

if (!Array.isArray(store.processedIds)) {
  store.processedIds = [];
}

if (store.processedIds.includes(id)) {
  // Duplicate: stop here by returning no items.
  return [];
}

store.processedIds.push(id);
return [{ json: payload }];

// Log the result of the run. In a real workflow this would write to a
// database or sheet. Here it just builds a small summary object.
const payload = $input.first().json;
return [{ json: { status: 'processed', id: payload.id, at: new Date().toISOString() } }];
